//! M2 integration: the whole path a real foundation takes.//!//! Build a container, wrap its file key to an age recipient, then recover everything from the//! wrapped key alone. This is the first test that exercises both crates together the way an//! export and an import actually would.use dome_core::{FoundationName, StorageSize};use dome_crypto::{    generate_file_key, generate_signing_keypair, signing_key_from_pkcs8, unwrap_file_key,    wrap_file_key,};use dome_image::FoundationFormat;use dome_image::FoundationManifest;use dome_image::reader::read_container;use dome_image::writer::{CHUNK_SIZE, write_container};#[test]fn a_container_survives_wrap_write_export_and_import() {    // The exporter: one signing identity, one age recipient for the key.    let (document, public) = generate_signing_keypair().expect("signing keypair");    let signing = signing_key_from_pkcs8(&document).expect("signing key");    let recipient_identity = age::x25519::Identity::generate();    let manifest = FoundationManifest::new(        FoundationName::new("dome/debian:bookworm-minimal").expect("name"),        FoundationFormat::DomeFoundation,        StorageSize::from_mib(4096).expect("size"),        "/var/lib/dome/foundations/debian.img",    );    // A payload bigger than one chunk, so the chunk table is exercised.    let mut payload = Vec::with_capacity(CHUNK_SIZE * 2 + 512);    for index in 0..(CHUNK_SIZE * 2 + 512) {        payload.push((index % 251) as u8);    }    let file_key = generate_file_key().expect("file key");    let bytes = write_container(&manifest, &payload, &file_key, &signing).expect("write");    // Only the wrapped key travels with the file; the key itself never does.    let wrapped = wrap_file_key(&file_key, &recipient_identity.to_public()).expect("wrap");    assert!(!wrapped.windows(32).any(|window| window == file_key));    // The importer: unwrap the key, then read.    let recovered_key = unwrap_file_key(&wrapped, &recipient_identity).expect("unwrap");    assert_eq!(recovered_key, file_key);    let read = read_container(&bytes, &recovered_key, &public).expect("read");    assert_eq!(read.payload, payload);    assert_eq!(read.chunk_count, 3);    assert_eq!(read.manifest.name.as_str(), "dome/debian:bookworm-minimal");    assert_eq!(read.manifest.virtual_size.as_mib(), 4096);}#[test]fn a_key_wrapped_for_someone_else_cannot_open_the_file() {    let (document, public) = generate_signing_keypair().expect("signing keypair");    let signing = signing_key_from_pkcs8(&document).expect("signing key");    let manifest = FoundationManifest::new(        FoundationName::new("dome/alpine:3.20").expect("name"),        FoundationFormat::DomeFoundation,        StorageSize::from_mib(512).expect("size"),        "/tmp/base.img",    );    let owner = age::x25519::Identity::generate();    let stranger = age::x25519::Identity::generate();    let file_key = generate_file_key().expect("file key");    let bytes = write_container(&manifest, b"private bytes", &file_key, &signing).expect("write");    let wrapped = wrap_file_key(&file_key, &owner.to_public()).expect("wrap");    // The stranger cannot unwrap, so the container stays closed to them.    assert!(unwrap_file_key(&wrapped, &stranger).is_err());    // The owner can.    let key = unwrap_file_key(&wrapped, &owner).expect("unwrap");    let read = read_container(&bytes, &key, &public).expect("read");    assert_eq!(read.payload, b"private bytes");}
